  return (
    <>
      <Container id="home" className="w-full p-4 md:p-5 mx-auto">
        <Suspense>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 1.5 }}
